import{_ as e,o as a,c as r,a3 as d}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Developer guide","description":"","frontmatter":{},"headers":[],"relativePath":"dev/index.md","filePath":"dev/index.md"}'),n={name:"dev/index.md"};function o(i,t,s,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="developer-guide" tabindex="-1">Developer guide <a class="header-anchor" href="#developer-guide" aria-label="Permalink to &quot;Developer guide&quot;">​</a></h1><p>This guide is for people who work on the platform&#39;s backend: the Laravel application that serves the admin panel, the center dashboard and the client app.</p><h2 id="what-the-platform-does" tabindex="-1">What the platform does <a class="header-anchor" href="#what-the-platform-does" aria-label="Permalink to &quot;What the platform does&quot;">​</a></h2><p>Clients browse riding and equestrian <strong>centers</strong>, look at the <strong>services</strong> each center offers, and book and pay for them. Centers manage their own services, schedules, team, promotions and payouts. The platform team (system users) manages centers, fees, plans, homepage content, notifications and analytics from the admin panel.</p><h2 id="how-this-guide-is-organised" tabindex="-1">How this guide is organised <a class="header-anchor" href="#how-this-guide-is-organised" aria-label="Permalink to &quot;How this guide is organised&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>What you find there</th></tr></thead><tbody><tr><td><a href="./getting-started/installation">Getting started</a></td><td>Installing, configuring and running the backend locally</td></tr><tr><td><a href="./architecture/overview">Architecture</a></td><td>The modular monolith, the three API surfaces and how Octane affects the code</td></tr><tr><td><a href="./conventions/coding">Conventions</a></td><td>How code is written here: money, permissions, tests, docs</td></tr><tr><td><a href="./domain/centers">Domain flows</a></td><td>How each module works, with its business rules</td></tr><tr><td><a href="./api/overview">API reference</a></td><td>Authentication, error format and a pointer to the endpoint reference</td></tr></tbody></table><p>The exact request and response of each endpoint is in the <a href="/docs" target="_self">endpoint reference</a>, generated from the code by Scribe.</p><h2 id="stack-at-a-glance" tabindex="-1">Stack at a glance <a class="header-anchor" href="#stack-at-a-glance" aria-label="Permalink to &quot;Stack at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Choice</th></tr></thead><tbody><tr><td>Language</td><td>PHP 8.3+ (8.4 in CI)</td></tr><tr><td>Framework</td><td>Laravel 13, served by Laravel Octane</td></tr><tr><td>Auth</td><td>Laravel Sanctum bearer tokens, one guard per API surface</td></tr><tr><td>Roles and permissions</td><td>Spatie Laravel Permission</td></tr><tr><td>Lists</td><td>Spatie Laravel Query Builder</td></tr><tr><td>Settings</td><td>Spatie Laravel Settings</td></tr><tr><td>Media</td><td>Spatie Laravel Media Library</td></tr><tr><td>Translatable fields</td><td>Spatie Laravel Translatable (<code>en</code> and <code>ar</code>)</td></tr><tr><td>Audit trail</td><td>Spatie Laravel Activitylog</td></tr><tr><td>Payments</td><td>Moyasar and Tamara gateways</td></tr><tr><td>Push</td><td>Firebase Cloud Messaging</td></tr><tr><td>Tests</td><td>Pest</td></tr><tr><td>API docs</td><td>Scribe</td></tr></tbody></table>',9)])])}const f=e(n,[["render",o]]);export{u as __pageData,f as default};
